const currentFarmDefaults={season:'Winter',day:1,year:1,weather:'Snowy',luck:'Neutral',gold:48219,hay:240,chickens:2,cows:1,ducks:0,goats:0,sheep:0,rabbits:0,pigs:0,farming:6,mining:4,foraging:6,fishing:2,combat:2,mine:46,pickaxe:'Basic',axe:'Copper',watering:'Basic',mayoMachines:2,cheesePresses:0,sprinklers:0,project:'Quality Sprinklers'};

function currentFarm(){
  let saved={};
  try{saved=JSON.parse(localStorage.getItem('spellStats')||'{}')}catch(e){}
  return {...currentFarmDefaults,...saved,cows:saved.cows??1,mayoMachines:saved.mayoMachines??saved.mayo??2,mine:saved.mine??46};
}

function inputField(label,key,type='number',options=[]){
  const v=currentFarm()[key];
  if(type==='select') return `<div class="field"><label for="farm-${key}">${label}</label><select id="farm-${key}" data-farm="${key}">${options.map(o=>`<option ${String(v)===String(o)?'selected':''}>${o}</option>`).join('')}</select></div>`;
  return `<div class="field"><label for="farm-${key}">${label}</label><input id="farm-${key}" data-farm="${key}" type="${type}" value="${v}" ${type==='number'?'min="0"':''}></div>`;
}

function makeDailyPlan(s){
  const animals=['chickens','cows','ducks','goats','sheep','rabbits','pigs'].reduce((n,k)=>n+(Number(s[k])||0),0);
  const plan=[];
  const products=[];
  if(+s.chickens) products.push('collect eggs'+(+s.mayoMachines?` and load up to ${s.mayoMachines} Mayo Machine${+s.mayoMachines===1?'':'s'}`:''));
  if(+s.cows) products.push('milk your cow'+(+s.cows===1?'':'s')+(+s.cheesePresses?` and start ${Math.min(+s.cows,+s.cheesePresses)} cheese`:''));
  if(+s.ducks) products.push('check for duck eggs');
  if(+s.goats) products.push('check for goat milk');
  if(+s.sheep||+s.rabbits) products.push('check for wool');
  if(+s.pigs) products.push(s.season==='Winter'?'keep pigs fed indoors; they cannot find truffles in Winter':'let pigs outside on a clear day to look for truffles');
  if(animals){
    const indoor=['Rainy','Snowy','Stormy'].includes(s.weather)||s.season==='Winter';
    plan.push({tag:'Start here',title:`Care for ${animals} animal${animals===1?'':'s'}`,text:`Pet everyone, ${indoor?`place ${animals} hay on the feeding benches`:'open the doors so they can eat fresh grass'}, then ${products.join('; ')||'collect any produce'}.`});
    if(+s.hay<animals*14) plan.push({tag:'Supply check',title:'Restock hay soon',text:`${s.hay} hay is under a two-week cushion for ${animals} animals (${animals*14} hay). Buy hay or plan grass and silos outside Winter.`});
  }
  const lucky=['Good','Very good'].includes(s.luck);
  if(+s.mine<120){
    const next=Math.min(120,Math.ceil((+s.mine+1)/5)*5);
    plan.push({tag:lucky?'Lucky-day outing':'Main outing',title:`Aim for mine floor ${next}`,text:`Bring food, leave space for ore, and use the elevator checkpoint. ${+s.mine<40?'Copper is common here.':+s.mine<80?'You are in the iron-rich region; keep coal for bars.':'Gold ore is common deeper down.'}`});
  }
  if(s.season!=='Winter'&&!['Rainy','Stormy'].includes(s.weather)) plan.unshift({tag:'Morning',title:'Water planted crops',text:'Water before the day gets away from you. Skip any tile already watered by a sprinkler.'});
  if(s.season==='Winter') plan.push({tag:'Winter option',title:'Forage or prepare Spring fields',text:'Use spare time for Winter forage, paths, sprinkler layout, tool upgrades, and organizing chests.'});
  const skills=['farming','mining','foraging','fishing','combat'];
  const lowest=skills.reduce((a,b)=>+s[a]<=+s[b]?a:b);
  plan.push({tag:'Gentle skill goal',title:`Practice ${lowest} for one short block`,text:`It is currently level ${s[lowest]}. Even one focused outing is enough; this is a menu, not a checklist.`});
  if(+s.day>=24) plan.push({tag:'Season end',title:'Check every crop deadline',text:'Most crops wither after day 28 unless they also grow next season. Count growth days before planting.'});
  if(s.project) plan.push({tag:'Your focus',title:s.project,text:'Before spending, write down the exact materials and keep those items in one labeled chest.'});
  return plan.slice(0,6);
}

