window.enhancedCropsPage=function(){
  main.innerHTML=header('Seasonal crop field guide','See each crop, how long it takes, whether it regrows, and the detail most likely to matter when planning a field.')+`<section class="crop-calculator"><div class="section-title"><div><p class="eyebrow">Planting planner</p><h2>Will it finish this season?</h2></div><p>Choose a crop and planting day to see the first harvest and every possible regrowth before day 28.</p></div><form id="cropCalcForm" class="crop-calc-form"><div class="field"><label for="calcSeason">Season</label><select id="calcSeason">${['Spring','Summer','Fall','Winter'].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="field"><label for="calcCrop">Crop</label><select id="calcCrop"></select></div><div class="field"><label for="calcPlantDay">Planting day</label><input id="calcPlantDay" type="number" min="1" max="28" value="1"></div><button class="button" type="submit">Calculate harvests</button></form><output id="cropCalcOutput" class="crop-calc-output" aria-live="polite"></output><p class="tiny">Assumes the crop is watered every day and uses no growth-speed fertilizer or profession bonus. Wheat can continue from Summer into Fall.</p></section><div class="crop-tabs" role="tablist">${['Spring','Summer','Fall','Winter'].map((s,i)=>`<button data-crop-season="${s}" class="${i===0?'active':''}">${s}</button>`).join('')}</div><div id="cropCards"></div><section class="section crop-knowledge"><div class="card-grid"><article class="card"><h3>Count growth days</h3><p>Planting day does not count. A 4-day crop planted and watered on day 1 is ready on day 5.</p></article><article class="card"><h3>Missing water pauses growth</h3><p>An unwatered crop does not die; it simply does not advance that day.</p></article><article class="card"><h3>Protect your walking lanes</h3><p>Green Beans, Hops, and Grapes use trellises and cannot be walked through.</p></article><article class="card"><h3>Watch day 28</h3><p>Most crops wither when the season changes unless they also grow next season.</p></article></div></section><p class="tiny source-note">Crop sprites and mechanics reference: Stardew Valley Wiki.</p>`;
  const draw=season=>{const rows=Object.entries(cropNotes).filter(([,v])=>v[0].includes(season)||v[0]==='Any');document.querySelector('#cropCards').innerHTML=`<div class="reference-grid">${rows.map(([name,v])=>`<article class="reference-card crop-card"><img src="assets/crops/${slugify(name)}.png" alt="${name}" loading="lazy"><div><p class="eyebrow">${v[0]}</p><h2>${name}</h2><dl><div><dt>Growth</dt><dd>${v[1]}</dd></div><div><dt>Harvest</dt><dd>${v[2]}</dd></div></dl><p>${v[3]}</p><p class="seed-source"><strong>Seeds:</strong> ${seedSources[name]}</p></div></article>`).join('')}</div>`};
  const updateCropChoices=()=>{const season=document.querySelector('#calcSeason').value;document.querySelector('#calcCrop').innerHTML=crops[season].map(c=>`<option>${c[0]}</option>`).join('')};
  const calculate=()=>{const season=document.querySelector('#calcSeason').value,name=document.querySelector('#calcCrop').value,day=Math.min(28,Math.max(1,+document.querySelector('#calcPlantDay').value||1)),row=crops[season].find(c=>c[0]===name),growth=row[1],first=day+growth,latest=28-growth,match=row[3].match(/regrows every (\d+) days/i),regrow=/regrows daily/i.test(row[3])?1:match?+match[1]:0;document.querySelector('#calcPlantDay').value=day;let html;if(first>28){html=`<strong>Too late for a harvest this season.</strong><span>${name} needs ${growth} growth days. Plant by day ${latest} for one harvest.</span>`}else{const count=regrow?1+Math.floor((28-first)/regrow):1,last=regrow?first+(count-1)*regrow:first;html=`<strong>First harvest: Day ${first}</strong><span>${regrow?`${count} harvests through Day ${last} if you keep picking it.`:'One harvest this season.'} Latest safe planting day: ${latest}.</span><span>Base sell value: ${row[2]}.</span>`}document.querySelector('#cropCalcOutput').innerHTML=html};
  draw('Spring');updateCropChoices();calculate();
  document.querySelector('#cropCalcForm').onsubmit=e=>{e.preventDefault();calculate()};
  document.querySelector('#calcSeason').onchange=e=>{updateCropChoices();calculate();document.querySelectorAll('[data-crop-season]').forEach(x=>x.classList.toggle('active',x.dataset.cropSeason===e.target.value));draw(e.target.value)};
  document.querySelector('#calcCrop').onchange=calculate;document.querySelector('#calcPlantDay').oninput=calculate;
  document.querySelectorAll('[data-crop-season]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-crop-season]').forEach(x=>x.classList.toggle('active',x===b));draw(b.dataset.cropSeason);document.querySelector('#calcSeason').value=b.dataset.cropSeason;updateCropChoices();calculate()});
};

