window.animalsPage=function(){const s=currentFarm();main.innerHTML=header('Farm animals & artisan goods','What each animal needs, where it lives, and what you can make from its produce.')+`<div class="notice current-note"><strong>Your current notes:</strong> ${s.chickens} chickens · ${s.cows} cow${+s.cows===1?'':'s'} · ${s.ducks} ducks · ${s.goats} goats · ${s.sheep} sheep · ${s.rabbits} rabbits · ${s.pigs} pigs · ${s.hay} hay. <a href="#dashboard">Update on My Farm</a></div><div class="reference-grid animal-grid">${animalData.map(a=>`<article class="reference-card animal-card"><img src="assets/animals/${a[1]}" alt="${a[0]}" loading="lazy"><div><p class="eyebrow">${a[2]} · ${a[3]}</p><h2>${a[0]}</h2><p><strong>Produces:</strong> ${a[4]}</p><p><strong>Make:</strong> ${a[5]}</p></div></article>`).join('')}</div><section class="section"><div class="section-title"><h2>Daily care in plain language</h2></div><div class="card-grid"><article class="card"><h3>Feed</h3><p>Each animal uses one portion a day. They prefer fresh grass outside; use hay indoors, during rain, and through Winter.</p></article><article class="card"><h3>Pet & collect</h3><p>Petting and consistent food build friendship. Collect products, then load the matching machine.</p></article><article class="card"><h3>Doors & weather</h3><p>Open doors for clear non-Winter days. Pigs only find truffles outside and do not find them in Winter or rain.</p></article></div></section><p class="tiny source-note">Animal prices, housing, and produce mechanics: Stardew Valley Wiki.</p>`};

const recipeData=[
  ['Fried Egg','fried-egg.png','Egg','Simple energy food; the first recipe many farms can make.'],['Omelet','omelet.png','Egg + Milk','Turns two animal products into a useful meal.'],['Salad','salad.png','Leek + Dandelion + Vinegar','A forage-friendly energy option.'],['Cheese Cauliflower','cheese-cauliflower.png','Cauliflower + Cheese','A strong use for Spring crops and cow cheese.'],['Baked Fish','baked-fish.png','Sunfish + Bream + Wheat Flour','Combines river fish with a pantry item.'],['Parsnip Soup','parsnip-soup.png','Parsnip + Milk + Vinegar','Useful reason to save one early parsnip.'],['Complete Breakfast','complete-breakfast.png','Fried Egg + Milk + Hashbrowns + Pancakes','Large energy boost with a Farming buff.'],['Lucky Lunch','lucky-lunch.png','Sea Cucumber + Tortilla + Blue Jazz','A powerful Luck meal for a mine day.'],['Glazed Yams','glazed-yams.png','Yam + Sugar','Good Fall crop-to-food conversion.'],['Sashimi','sashimi.png','Any fish','Turns inexpensive fish into a handy meal.'],['Roots Platter','roots-platter.png','Cave Carrot + Winter Root','Mining and Winter forage meal with an Attack buff.'],["Dish O' The Sea",'dish-o-the-sea.png','Sardine ×2 + Hashbrowns','Fishing buff for harder catches.'],["Miner's Treat",'miners-treat.png','Cave Carrot ×2 + Sugar + Milk','Mining and Magnetism buffs for cave trips.']
];
window.recipesPage=function(){main.innerHTML=header('Recipe box','A beginner-friendly collection of useful meals. Search by name, ingredient, or purpose.')+`<div class="directory-tools"><input id="recipeSearch" type="search" placeholder="Search recipes or ingredients…" aria-label="Search recipes"></div><div id="recipeGrid" class="reference-grid recipe-grid"></div><div class="notice"><strong>Before you cook:</strong> you need a kitchen from the first farmhouse upgrade (or a Cookout Kit). Food buffs do not stack with other food buffs, but one drink buff can run alongside one food buff.</div><p class="tiny source-note">Ingredients and buffs reference: Stardew Valley Wiki.</p>`;const draw=q=>{q=q.toLowerCase();document.querySelector('#recipeGrid').innerHTML=recipeData.filter(r=>r.join(' ').toLowerCase().includes(q)).map(r=>`<article class="reference-card recipe-card"><img src="assets/recipes/${r[1]}" alt="${r[0]}" loading="lazy"><div><h2>${r[0]}</h2><p><strong>Ingredients:</strong> ${r[2]}</p><p>${r[3]}</p></div></article>`).join('')||'<p>No matching recipes yet.</p>'};draw('');document.querySelector('#recipeSearch').oninput=e=>draw(e.target.value)};

const buildingData=[
  ['Coop','4,000g · 300 Wood · 100 Stone','6×3 · 3 days','Houses 4 coop animals'],['Big Coop','10,000g · 400 Wood · 150 Stone','upgrade · 2 days','Houses 8; incubator; unlocks ducks'],['Deluxe Coop','20,000g · 500 Wood · 200 Stone','upgrade · 2 days','Houses 12; auto-feeder; unlocks rabbits'],['Barn','6,000g · 350 Wood · 150 Stone','7×4 · 3 days','Houses 4 barn animals'],['Big Barn','12,000g · 450 Wood · 200 Stone','upgrade · 2 days','Houses 8; unlocks goats'],['Deluxe Barn','25,000g · 550 Wood · 300 Stone','upgrade · 2 days','Houses 12; auto-feeder; unlocks sheep and pigs'],['Silo','100g · 100 Stone · 10 Clay · 5 Copper Bars','3×3 · 2 days','Stores 240 hay'],['Well','1,000g · 75 Stone','3×3 · 2 days','Refill a watering can'],['Mill','2,500g · 50 Stone · 150 Wood · 4 Cloth','4×2 · 2 days','Processes wheat, beets, and rice'],['Shed','15,000g · 300 Wood','7×3 · 2 days','Indoor machine or storage space'],['Big Shed','20,000g · 550 Wood · 300 Stone','upgrade · 2 days','Doubles the shed interior'],['Fish Pond','5,000g · 200 Stone · 5 Seaweed · 5 Green Algae','5×5 · 2 days','Raises fish and produces roe/items'],['Stable','10,000g · 100 Hardwood · 5 Iron Bars','4×2 · 2 days','Includes a horse for faster travel'],['Slime Hutch','10,000g · 500 Stone · 10 Refined Quartz · 1 Iridium Bar','7×4 · 2 days','Raises up to 20 slimes; a later-game project'],['Cabin','100g','5×3 · instant','A home for one multiplayer farmhand'],['Shipping Bin','250g · 150 Wood','2×1 · instant','Adds another nightly shipping box'],['Pet Bowl','5,000g · 25 Hardwood','2×2 · instant','Dedicated home for one additional pet'],['Farmhouse Upgrade 1','10,000g · 450 Wood','3 days','Adds a kitchen and larger bedroom'],['Farmhouse Upgrade 2','65,000g · 100 Hardwood','3 days','Adds two rooms and unlocks renovations'],['Farmhouse Upgrade 3','100,000g','3 days','Adds a cellar with casks']
];
const buildingImages={'Coop':'coop.png','Big Coop':'big-coop.png','Deluxe Coop':'deluxe-coop.png','Barn':'barn.png','Big Barn':'big-barn.png','Deluxe Barn':'deluxe-barn.png','Silo':'silo.png','Well':'well.png','Mill':'mill.png','Shed':'shed.png','Big Shed':'big-shed.png','Fish Pond':'fish-pond.png','Stable':'horse-stable.png','Slime Hutch':'slime-hutch.png','Cabin':'log-cabin-stage-1.png','Shipping Bin':'shipping-bin.gif','Pet Bowl':'pet-bowl-wood.png','Farmhouse Upgrade 1':'house-tier-1.png','Farmhouse Upgrade 2':'house-tier-2.png','Farmhouse Upgrade 3':'house-tier-3.png'};
window.buildingsPage=function(){main.innerHTML=header('Farm constructions','Robin’s core farm buildings and farmhouse upgrades—with pictures, materials, space, and build time in one planning reference.')+`<div class="reference-grid building-grid">${buildingData.map(b=>`<article class="reference-card building-card"><img src="assets/buildings/${buildingImages[b[0]]}" alt="${b[0]}" loading="lazy"><div><p class="eyebrow">${b[2]}</p><h2>${b[0]}</h2><p><strong>Cost:</strong> ${b[1]}</p><p>${b[3]}</p></div></article>`).join('')}</div><div class="notice"><strong>Planning tip:</strong> clear the full footprint and a walking border before visiting Robin. Upgrades apply to an existing building; they do not need a second footprint.</div><p class="tiny source-note">Building images, costs, footprints, and build times reference: Stardew Valley Wiki. Cosmetic house renovations are not listed because their options depend on upgrade progress.</p>`};

const weaponData=[
  ['Rusty Sword','rusty-sword.png','Sword · 2–5 damage','Given by Marlon at the Mines entrance.'],['Steel Smallsword','steel-smallsword.png','Sword · 4–8 damage','Chest reward on mine floor 20.'],['Silver Saber','silver-saber.png','Sword · 8–15 damage','Adventurer’s Guild for 750g after reaching floor 20.'],['Crystal Dagger','crystal-dagger.png','Dagger · 4–10 damage','Chest reward on mine floor 60. Its special move is a quick flurry.'],['Bone Sword','bone-sword.png','Sword · 20–30 damage','Guild for 6,000g after floor 75, or occasionally dropped by Skeletons.'],['Obsidian Edge','obsidian-edge.png','Sword · 30–45 damage','Chest reward on mine floor 90.'],['Lava Katana','lava-katana.png','Sword · 55–64 damage','Guild for 25,000g after reaching floor 120.'],['Slingshot','slingshot.png','Ranged · damage depends on ammo','Chest reward on mine floor 40. Load ammo before using it.'],['Master Slingshot','master-slingshot.png','Ranged · about 2× regular damage','Chest reward on mine floor 70.']
];
window.weaponsPage=function(){main.innerHTML=header('Weapons & upgrades','Where stronger weapons come from now, where true forging happens later, and exactly what each route needs.')+`<div class="notice weapon-answer"><strong>Important:</strong> Clint upgrades tools—not weapons. In Year 1, replace a weapon with a stronger mine reward or buy one from the Adventurer’s Guild, just east of the Mines.</div><section class="weapon-place"><div><p class="eyebrow">Early-game weapon upgrades</p><h2>Adventurer’s Guild</h2><p><strong>Where:</strong> east of the Mines. <strong>When:</strong> 2:00pm–2:00am after the Initiation quest. <strong>What you need:</strong> gold and the mine-floor requirement shown on each weapon. Marlon’s stock expands as you reach deeper checkpoints.</p></div><img src="assets/weapons/rusty-sword.png" alt="Rusty Sword" loading="lazy"></section><div class="reference-grid weapon-grid">${weaponData.map(w=>`<article class="reference-card weapon-card"><img src="assets/weapons/${w[1]}" alt="${w[0]}" loading="lazy"><div><p class="eyebrow">${w[2]}</p><h2>${w[0]}</h2><p>${w[3]}</p></div></article>`).join('')}</div><section class="section"><div class="section-title"><div><p class="eyebrow">True weapon improvement</p><h2>Forge requirements</h2></div><p>Later-game location details are kept inside this clearly labeled section.</p></div><div class="upgrade-grid"><article class="card"><span class="badge">Where</span><h3>Volcano Dungeon · floor 10</h3><p>The Forge is in the final room. Bring the weapon, a gemstone, and Cinder Shards.</p></article><article class="card"><span class="badge">Three forge levels</span><h3>10 · 15 · 20 Cinder Shards</h3><p>The first, second, and third gemstone forges cost 10, 15, and 20 shards—a total of 45.</p></article><article class="card"><span class="badge">Enchant</span><h3>Prismatic Shard + 20 Cinder Shards</h3><p>Applies one random enchantment. Enchanting is separate from the three gemstone stat forges.</p></article></div><div class="forge-table-wrap"><table class="forge-table"><thead><tr><th>Gem</th><th>Weapon effect per forge</th><th>Bring with it</th></tr></thead><tbody><tr><th>Ruby</th><td>+10% damage</td><td>10, then 15, then 20 Cinder Shards</td></tr><tr><th>Emerald</th><td>More weapon speed</td><td>One Emerald per forge</td></tr><tr><th>Aquamarine</th><td>More critical-hit chance</td><td>One Aquamarine per forge</td></tr><tr><th>Jade</th><td>More critical-hit power</td><td>One Jade per forge</td></tr><tr><th>Amethyst</th><td>More knockback</td><td>One Amethyst per forge</td></tr><tr><th>Topaz</th><td>More defense</td><td>One Topaz per forge</td></tr></tbody></table></div></section><section class="section"><div class="section-title"><h2>Choose your weapon style</h2></div><div class="card-grid"><article class="card"><h3>Sword</h3><p>The easiest all-rounder. Its special move blocks and knocks enemies back.</p></article><article class="card"><h3>Dagger</h3><p>Very fast and close-range. Its special move delivers several quick stabs.</p></article><article class="card"><h3>Club</h3><p>Slower, heavy hits with strong knockback. Its special move slams nearby enemies.</p></article></div></section><div class="notice"><strong>Looking for axe, pickaxe, hoe, or watering-can upgrades?</strong> Visit Clint’s Blacksmith with 5 matching bars and the required gold. Use the <a href="#tools">Tool Upgrade Planner</a> for the exact total from your current tier.</div><p class="tiny source-note">Weapon pictures, damage, Guild unlocks, and Forge requirements reference: Stardew Valley Wiki.</p>`};

const skillSections={
  Farming:[['How XP grows','Harvesting crops earns Farming XP. Petting, milking, shearing, and collecting an animal product inside its building each add a small amount. Watering and hoeing alone do not award Farming XP.'],['What each level changes','Every Farming level improves hoe and watering-can proficiency, reducing their energy cost. Most levels also unlock a recipe; levels 5 and 10 are profession choices.'],['Morning order','Check weather, pet and feed animals, collect produce, then water only the tiles not covered by sprinklers. Process eggs and milk while you finish the rest of the route.'],['Crop math','Growth time starts after planting day. Count forward from the next morning and leave room before day 28. Use the crop planner before buying a late-season seed batch.'],['Machine rhythm','Turn repeatable raw products into artisan goods: eggs → mayonnaise, milk → cheese, wool → cloth, and truffles → oil. Keep one machine lane clear and easy to reach.'],['Your current focus',()=>`Your current note says Farming ${currentFarm().farming}. Quality Sprinklers are already unlocked at level 6, so gathering iron, gold, and refined quartz is a practical next step.`]],
  Mining:[['How XP grows','Breaking rocks and ore nodes earns Mining XP; the amount varies by rock. Bombs can still award the XP when they destroy a rock. Swinging the pickaxe without breaking anything does not.'],['What each level changes','Every Mining level improves pickaxe proficiency, so each swing costs less energy. Recipe unlocks include bombs, transmutation, and useful cave equipment.'],['Elevator checkpoints','The elevator records every five floors. Aim for the next multiple of five instead of pushing until collapse; a saved checkpoint makes every future trip easier.'],['Ore regions','Copper is common on floors 1–39, iron on 40–79, and gold on 80+. Match the day’s material goal to the floor range instead of clearing random levels.'],['Pack for the trip','Bring food, leave inventory space, place weapon and pickaxe side by side, and watch both health and time. Ladders matter more than breaking every rock.'],['Your current route',()=>`Your notes say Mining ${currentFarm().mining} and mine floor ${currentFarm().mine}. The next gentle elevator checkpoint is ${Math.min(120,Math.ceil((+currentFarm().mine+1)/5)*5)}; the frozen floors are also your best current iron route.`]],
  Fishing:[['How XP grows','Catching fish and collecting baited Crab Pots raise Fishing. Trash still gives a little practice value, and a successful catch matters more than whether the fish sells for much.'],['What each level changes','Fishing levels make the green fishing bar larger and improve rod proficiency. Temporary food buffs can raise the effective level even before the next permanent level.'],['The four variables','A catch depends on season, location, time, and weather. If one fish will not appear, check all four before assuming your rod is the problem.'],['Gentle training plan','At low levels, use the Training Rod and practice at the mountain lake or another calm favorite spot. Ten relaxed casts are a useful session; perfection is unnecessary.'],['Treasure vs catch','Do not chase a treasure chest if it makes you lose the fish. Secure easy catches first, then experiment with treasure when the fish stays calm.'],['Your current focus',()=>`Your current note says Fishing ${currentFarm().fishing}. Short practice sessions, the Training Rod, and a fishing-food buff will make the biggest immediate difference.`]],
  Foraging:[['How XP grows','Pick up forage from the ground and chop trees with an axe. Tree-felling XP arrives when the tree falls; removing the stump adds a little more.'],['What each level changes','Every Foraging level improves axe proficiency. Recipes gradually unlock seasonal Wild Seeds, the Tapper, useful travel items, and more.'],['Winter routine','Scan snow for forage and visible artifact or seed spots, then use spare energy on planned tree work. Leave young trees space if you want a renewable wood lot.'],['Wild Seeds','Seasonal Wild Seeds grow into forage, use Foraging quality rules, and make a calm way to multiply found items. Winter Seeds unlock at Foraging 7.'],['Wood planning','Keep ordinary Wood and Hardwood in separate goals. Hardwood comes from tougher stumps and logs that require upgraded axes; do not sell it casually.'],['Your current focus',()=>`Your current note says Foraging ${currentFarm().foraging}. Level 7 is your next recipe milestone and unlocks Winter Seeds—especially relevant during your first Winter.`]],
  Combat:[['How XP grows','Defeating monsters raises Combat. Weapons themselves use no energy, so food and safe positioning are mainly about protecting health and extending the trip.'],['What each level changes','Combat levels raise maximum health at several milestones and unlock combat recipes. Levels 5 and 10 offer profession choices for damage, critical hits, or defense-oriented play.'],['Position first','Fight from open tiles, keep enemies on one side of you, and use knockback to create space. Narrow passages are safer than being surrounded in a large room.'],['Weapon rhythm','Swords are forgiving, daggers are fast and close-range, and clubs trade speed for heavy knockback. Use the special move when its cooldown is ready.'],['Leave on purpose','A successful trip can end before fainting. Eat before health becomes critical, keep a clear route to the ladder, and stop when the clock or supplies feel uncomfortable.'],['Your current focus',()=>`Your current note says Combat ${currentFarm().combat}. A stronger mine-floor reward or Adventurer’s Guild purchase will help more right now than worrying about late-game forging.`]]
};
window.fieldGuidePage=function(){main.innerHTML=header('Five-skill field guide','Deeper, practical guides for Farming, Mining, Fishing, Foraging, and Combat—plus advice shaped by your current farm notes.')+`<div class="skill-overview notice"><strong>How skills work:</strong> each skill has 10 levels. Levels improve related tool proficiency, most levels unlock recipes overnight, and levels 5 and 10 offer profession choices. Food buffs are temporary and can raise a skill beyond its current permanent level.</div><div class="skill-tabs" role="tablist">${Object.keys(skillSections).map((s,i)=>`<button class="${i===0?'active':''}" data-skill="${s}" role="tab">${s}</button>`).join('')}</div><div id="skillPanel"></div><p class="tiny source-note">Skill XP, proficiency, recipe, and profession mechanics reference: Stardew Valley Wiki.</p>`;const levelFor=s=>currentFarm()[s.toLowerCase()]??0;const draw=s=>{document.querySelector('#skillPanel').innerHTML=`<div class="skill-level-banner"><span>${s}</span><strong>Current note: Level ${levelFor(s)}</strong></div><div class="card-grid skill-grid">${skillSections[s].map(x=>`<article class="card"><h3>${x[0]}</h3><p>${typeof x[1]==='function'?x[1]():x[1]}</p></article>`).join('')}</div>`};draw('Farming');document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-skill]').forEach(x=>x.classList.toggle('active',x===b));draw(b.dataset.skill)})};

window.enhancedToolsPage=function(){
  const toolSteps=[['Copper',2000,'Copper'],['Steel',5000,'Iron'],['Gold',10000,'Gold'],['Iridium',25000,'Iridium']];
  const pricedCrops=Object.keys(seedSources);
  main.innerHTML=header('Farm calculators','Five practical planners for feed, sprinklers, tool upgrades, smelting, and seed shopping. Results stay in this browser and never change your game.')+`<div class="calculator expanded-calculator">
  <section class="calc-card"><p class="eyebrow">Animal care</p><h2>Hay supply</h2><div class="field"><label for="hayAmount">Hay in storage</label><input id="hayAmount" type="number" min="0" value="${currentFarm().hay}"></div><div class="field"><label for="animalCount">Animals eating indoors</label><input id="animalCount" type="number" min="1" value="${Math.max(1,+currentFarm().chickens + +currentFarm().cows + +currentFarm().ducks + +currentFarm().goats + +currentFarm().sheep + +currentFarm().rabbits + +currentFarm().pigs)}"></div><output id="hayOutput"></output><p class="tiny">Assumes one hay per animal per day and no outdoor grass. One standard silo holds 240 hay.</p></section>
  <section class="calc-card"><p class="eyebrow">Spring planning</p><h2>Quality Sprinkler field</h2><div class="field"><label for="cropTiles">Crop tiles to water</label><input id="cropTiles" type="number" min="1" value="64"></div><output id="sprinklerOutput"></output><p class="tiny">Each Quality Sprinkler waters 8 surrounding tiles and costs 1 Iron Bar, 1 Gold Bar, and 1 Refined Quartz.</p></section>
  <section class="calc-card"><p class="eyebrow">Clint’s Blacksmith</p><h2>Tool Upgrade Planner</h2><div class="calc-pair"><div class="field"><label for="toolStart">Current tier</label><select id="toolStart"><option>Basic</option><option>Copper</option><option>Steel</option><option>Gold</option></select></div><div class="field"><label for="toolTarget">Target tier</label><select id="toolTarget"><option>Copper</option><option>Steel</option><option selected>Gold</option><option>Iridium</option></select></div></div><output id="toolOutput"></output><p class="tiny">Clint requires each tier in order. Every step takes two days and uses 5 matching bars.</p></section>
  <section class="calc-card"><p class="eyebrow">Furnace materials</p><h2>Smelting planner</h2><div class="field"><label for="barCount">Bars you want to make</label><input id="barCount" type="number" min="1" value="8"></div><div class="field"><label for="oreOwned">Matching ore already owned</label><input id="oreOwned" type="number" min="0" value="0"></div><output id="smeltOutput"></output><p class="tiny">A standard Copper, Iron, Gold, or Iridium Bar uses 5 matching ore and 1 Coal.</p></section>
  <section class="calc-card"><p class="eyebrow">Seed shopping</p><h2>Crop budget</h2><div class="field"><label for="budgetCrop">Crop</label><select id="budgetCrop">${pricedCrops.map(n=>`<option>${n}</option>`).join('')}</select></div><div class="field"><label for="seedCount">Seeds to buy</label><input id="seedCount" type="number" min="1" value="24"></div><output id="seedOutput"></output><p class="tiny">Uses the regular source and price listed in the crop guide. Special and crafted seeds are labeled instead of given a false shop price.</p></section>
  </div><p class="tiny source-note">Tool costs, smelting recipes, seed prices, hay use, and sprinkler coverage reference: Stardew Valley Wiki.</p>`;
  const calcHay=()=>{const h=Math.max(0,+document.querySelector('#hayAmount').value||0),a=Math.max(1,+document.querySelector('#animalCount').value||1),days=Math.floor(h/a),winterNeed=a*28;document.querySelector('#hayOutput').innerHTML=`<strong>${days} full indoor days</strong><span>${h>=winterNeed?`${h-winterNeed} hay left after a 28-day Winter.`:`Need ${winterNeed-h} more hay for 28 indoor days.`}</span>`};
  const calcSpr=()=>{const tiles=Math.max(1,+document.querySelector('#cropTiles').value||1),n=Math.ceil(tiles/8);document.querySelector('#sprinklerOutput').innerHTML=`<strong>${n} Quality Sprinkler${n===1?'':'s'}</strong><span>Waters up to ${n*8} tiles · ${n} Iron Bars · ${n} Gold Bars · ${n} Refined Quartz.</span>`};
  const calcTool=()=>{const names=['Basic','Copper','Steel','Gold','Iridium'],start=names.indexOf(document.querySelector('#toolStart').value),target=names.indexOf(document.querySelector('#toolTarget').value),out=document.querySelector('#toolOutput');if(target<=start){out.innerHTML='<strong>No upgrade steps needed</strong><span>Choose a target tier above the current tier.</span>';return}const steps=toolSteps.slice(start,target),gold=steps.reduce((n,s)=>n+s[1],0);out.innerHTML=`<strong>${gold.toLocaleString()}g total · ${steps.length*2} upgrade days</strong><span>${steps.map(s=>`5 ${s[2]} Bars → ${s[0]}`).join(' · ')}</span>`};
  const calcSmelt=()=>{const bars=Math.max(1,+document.querySelector('#barCount').value||1),owned=Math.max(0,+document.querySelector('#oreOwned').value||0),need=bars*5;document.querySelector('#smeltOutput').innerHTML=`<strong>${need} ore · ${bars} Coal</strong><span>${owned>=need?'You already have enough ore.':`Mine or buy ${need-owned} more matching ore.`}</span>`};
  const calcSeeds=()=>{const name=document.querySelector('#budgetCrop').value,count=Math.max(1,+document.querySelector('#seedCount').value||1),source=seedSources[name],match=source.match(/·\s*([\d,]+)g/),out=document.querySelector('#seedOutput');out.innerHTML=match?`<strong>${(count*Number(match[1].replaceAll(',',''))).toLocaleString()}g for ${count}</strong><span>${source}</span>`:`<strong>Not a regular gold purchase</strong><span>${source}</span>`};
  ['hayAmount','animalCount'].forEach(id=>document.querySelector('#'+id).oninput=calcHay);document.querySelector('#cropTiles').oninput=calcSpr;['toolStart','toolTarget'].forEach(id=>document.querySelector('#'+id).onchange=calcTool);['barCount','oreOwned'].forEach(id=>document.querySelector('#'+id).oninput=calcSmelt);document.querySelector('#budgetCrop').onchange=calcSeeds;document.querySelector('#seedCount').oninput=calcSeeds;calcHay();calcSpr();calcTool();calcSmelt();calcSeeds();
};

route();
